package kr.memorynotes;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.graphics.pdf.PdfRenderer;
import android.os.ParcelFileDescriptor;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.DigestInputStream;
import java.util.*;
import java.util.zip.*;

/** Complete local backup. Originals are streamed, including externally linked PDFs. */
public final class PdfFullBackup {
 private static final String FORMAT="memorynote-full";
 private static final String JOURNAL="pdf-full-restore-transaction.json";
 private static volatile boolean operationActive;
 private static synchronized void begin(MainActivity a)throws Exception{if(operationActive)throw new IOException("전체 백업 또는 복원이 진행 중입니다. 완료 후 다시 시도해 주세요.");recoverChecked(a);operationActive=true;}
 private static synchronized void end(){operationActive=false;}
 private static File stage(MainActivity a,String name)throws IOException{File f=new File(a.getFilesDir(),name+UUID.randomUUID());if(!f.mkdirs())throw new IOException("백업 임시 공간을 만들 수 없습니다.");return f;}
 private static void remove(File f){File[] list=f.listFiles();if(list!=null)for(File c:list)remove(c);f.delete();}
 private static long copy(InputStream in,OutputStream out,long maximum,PdfArchiveRules.Budget budget)throws IOException{byte[] b=new byte[65536];long bytes=0;int n;while((n=in.read(b))!=-1){if(n>maximum-bytes)throw new IOException("백업 항목 크기 제한을 초과했습니다.");bytes+=n;if(budget!=null)budget.bytes(n);out.write(b,0,n);}return bytes;}
 private static JSONObject json(File f,long max)throws Exception{try(InputStream in=new FileInputStream(f);ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,max,null);return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}
 private static void write(File file,JSONObject data)throws Exception{try(FileOutputStream out=new FileOutputStream(file)){out.write(data.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();}}
 private static JSONObject state(File folder)throws Exception{File f=new File(folder,"state.json");if(!f.exists()&&!new File(f.getPath()+".bak").exists())return new JSONObject().put("docs",new JSONArray()).put("notes",new JSONObject());try(InputStream in=new AtomicFile(f).openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,PdfArchiveRules.META,null);return new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}}
 private static long put(ZipOutputStream zip,String name,InputStream in,PdfArchiveRules.Budget budget)throws Exception{long max=budget.entry(name,false);zip.putNextEntry(new ZipEntry(name));long count;try(InputStream source=in){count=copy(source,zip,max,budget);}zip.closeEntry();return count;}
 private static void putJson(ZipOutputStream zip,String name,JSONObject o,PdfArchiveRules.Budget budget)throws Exception{put(zip,name,new ByteArrayInputStream(o.toString().getBytes(StandardCharsets.UTF_8)),budget);}
 public static void exportTo(MainActivity a,OutputStream output)throws Exception{begin(a);try{exportChecked(a,output);}finally{end();}}
 private static void exportChecked(MainActivity a,OutputStream output)throws Exception{
  File work=stage(a,"full-backup-");try{
   File nativeZip=new File(work,"notes.zip");try(OutputStream out=new FileOutputStream(nativeZip)){new BackupManager(a,a.db).exportTo(out);}
   // Use the native backup's exact snapshot, rather than racing a second DB read.
   File nativeStage=new File(work,"native");nativeStage.mkdir();Set<String> nativeEntries=extractNative(nativeZip,nativeStage);JSONObject snapshot=json(new File(nativeStage,"notes.json"),PdfArchiveRules.META);BackupManager.validate(snapshot,nativeEntries);validateReferences(snapshot);
   File folder=new File(a.getFilesDir(),"pdfstudy");JSONObject metadata=state(folder);pruneOrphans(metadata,snapshot);JSONArray docs=metadata.optJSONArray("docs");if(docs==null){docs=new JSONArray();metadata.put("docs",docs);}PdfArchiveRules.Budget budget=new PdfArchiveRules.Budget();
   try(ZipOutputStream zip=new ZipOutputStream(new BufferedOutputStream(output))){
    putJson(zip,"manifest.json",new JSONObject().put("format",FORMAT).put("version",1),budget);put(zip,"notes.zip",new FileInputStream(nativeZip),budget);
    for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);String id=d.getString("id");PdfArchiveRules.id(id);try(ParcelFileDescriptor fd=PdfDocuments.open(a,folder,d);PdfRenderer pdf=new PdfRenderer(fd)){if(pdf.getPageCount()!=d.getInt("pages"))throw new IOException("PDF 원본이 변경되었습니다. 문서를 다시 연결한 후 백업해 주세요.");}MessageDigest hash=MessageDigest.getInstance("SHA-256");long size;try(InputStream in=new DigestInputStream(PdfDocuments.input(a,folder,d),hash)){size=put(zip,"pdf/"+id+".pdf",in,budget);}d.put("bytes",size).put("sha256",hex(hash.digest()));d.remove("uri");}
    File[] files=folder.listFiles();Set<String> inkNames=new HashSet<String>();if(files!=null)for(File f:files){String name=f.getName();if(name.endsWith(".ink.json.bak"))name=name.substring(0,name.length()-4);if(name.endsWith(".ink.json"))inkNames.add(name);}for(String name:inkNames){String doc=inkDoc(name,docs);if(doc==null)continue;File f=new File(folder,name);validateInk(f);put(zip,"pdf/"+name,new AtomicFile(f).openRead(),budget);}
    putJson(zip,"pdf/state.json",metadata,budget);
   }
  }finally{remove(work);}
 }
 public static void restoreFrom(MainActivity a,InputStream input)throws Exception{begin(a);try{restoreChecked(a,input);}finally{end();}}
 private static void restoreChecked(MainActivity a,InputStream input)throws Exception{
  File work=stage(a,"full-restore-");ArrayList<File> installed=new ArrayList<File>();File live=new File(a.getFilesDir(),"pdfstudy"),recovery=null;boolean journaled=false,cleanup=true;
  try{
   Set<String> entries=extract(input,work);if(!entries.contains("manifest.json")||!entries.contains("notes.zip")||!entries.contains("pdf/state.json"))throw new IOException("완전한 PDF·노트 백업이 아닙니다.");
   JSONObject manifest=json(new File(work,"manifest.json"),PdfArchiveRules.META);if(!FORMAT.equals(manifest.getString("format"))||manifest.getInt("version")!=1)throw new IOException("지원하지 않는 전체 백업입니다.");
   File nativeStage=new File(work,"native");nativeStage.mkdir();Set<String> nativeEntries=extractNative(new File(work,"notes.zip"),nativeStage);JSONObject snapshot=json(new File(nativeStage,"notes.json"),PdfArchiveRules.META);BackupManager.validate(snapshot,nativeEntries);validateImages(nativeStage,nativeEntries);
   JSONObject metadata=json(new File(work,"pdf/state.json"),PdfArchiveRules.META);validateReferences(snapshot);validateMetadata(metadata,snapshot,entries,new File(work,"pdf"));
   // A durable pre-restore DB snapshot plus the untouched image files makes old data recoverable.
   recovery=stage(a,"full-restore-recovery-");JSONObject beforeNotes=a.db.snapshot();File oldNotes=new File(recovery,"notes.json");write(oldNotes,beforeNotes);if(oldNotes.length()>PdfArchiveRules.META)throw new IOException("기존 노트 복구 기록이 크기 제한을 초과합니다.");
   HashMap<String,String> mapping=new HashMap<String,String>();File imageDir=new File(a.getFilesDir(),"images");if(!imageDir.isDirectory()&&!imageDir.mkdirs())throw new IOException("사진 저장 공간을 만들 수 없습니다.");
   for(String name:nativeEntries)if(name.startsWith("images/")){String old=name.substring(7),next=UUID.randomUUID()+".img";File target=new File(imageDir,next);if(target.exists())throw new IOException("사진 파일 충돌");installed.add(target);mapping.put(old,next);}
   JSONArray imageNames=new JSONArray();for(File f:installed)imageNames.put(f.getName());JSONObject journal=new JSONObject().put("phase","pending").put("recovery",recovery.getName()).put("work",work.getName()).put("hadOld",live.exists()).put("images",imageNames);journal(a,journal);journaled=true;
   for(String name:nativeEntries)if(name.startsWith("images/")){File target=new File(imageDir,mapping.get(name.substring(7)));try(InputStream in=new FileInputStream(new File(nativeStage,name));FileOutputStream out=new FileOutputStream(target)){copy(in,out,25L*1024*1024,null);out.getFD().sync();}}
   remap(snapshot,metadata,mapping);write(new File(work,"pdf/state.json"),metadata);
   File oldPdf=new File(recovery,"pdfstudy");if(journal.getBoolean("hadOld")&&!live.renameTo(oldPdf))throw new IOException("기존 PDF 자료를 보호할 수 없어 복원을 중단했습니다.");
   if(!new File(work,"pdf").renameTo(live))throw new IOException("PDF 자료를 설치하지 못했습니다.");
   // Native restore is transactional. Every archive item has been staged and validated above.
   a.db.restore(snapshot);verifySnapshot(snapshot,a.db.snapshot());journal.put("phase","done");journal(a,journal);finishJournal(a,journal);
  }catch(Exception error){
   if(journaled)try{recoverChecked(a);}catch(Exception rollback){cleanup=false;error.addSuppressed(rollback);error.addSuppressed(new IOException("복구 자료 위치: "+recovery));}else if(recovery!=null)remove(recovery);
   throw error;
  }finally{if(cleanup)remove(work);}
 }
 /** Invoke immediately after MainActivity.db initialization, before displaying notes. */
 public static synchronized boolean recoverPending(MainActivity a){if(operationActive)return false;try{recoverChecked(a);return true;}catch(Exception e){a.error(new IOException("중단된 전체 복원을 복구하지 못했습니다. 기존 복구 기록은 유지됩니다.",e));return false;}}
 private static void journal(MainActivity a,JSONObject data)throws Exception{AtomicFile atomic=new AtomicFile(new File(a.getFilesDir(),JOURNAL));FileOutputStream out=null;try{out=atomic.startWrite();out.write(data.toString().getBytes(StandardCharsets.UTF_8));out.getFD().sync();atomic.finishWrite(out);}catch(Exception e){if(out!=null)atomic.failWrite(out);throw e;}}
 private static File journalPath(MainActivity a,JSONObject j,String key,String prefix)throws Exception{String name=j.getString(key);if(!name.matches(prefix+"[0-9a-fA-F-]{36}"))throw new IOException("잘못된 복원 복구 경로");return new File(a.getFilesDir(),name);}
 private static void finishJournal(MainActivity a,JSONObject j)throws Exception{remove(journalPath(a,j,"recovery","full-restore-recovery-"));remove(journalPath(a,j,"work","full-restore-"));new AtomicFile(new File(a.getFilesDir(),JOURNAL)).delete();}
 private static void recoverChecked(MainActivity a)throws Exception{
  File marker=new File(a.getFilesDir(),JOURNAL);if(!marker.exists()&&!new File(marker.getPath()+".bak").exists()){File[] files=a.getFilesDir().listFiles();if(files!=null)for(File f:files)if(f.getName().matches("(?:full-restore-|full-backup-)[0-9a-fA-F-]{36}"))remove(f);return;}JSONObject j;try(InputStream in=new AtomicFile(marker).openRead();ByteArrayOutputStream bytes=new ByteArrayOutputStream()){copy(in,bytes,PdfArchiveRules.META,null);j=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8));}
  if("done".equals(j.getString("phase"))){finishJournal(a,j);return;}if(!"pending".equals(j.getString("phase")))throw new IOException("알 수 없는 복구 단계");
  File recovery=journalPath(a,j,"recovery","full-restore-recovery-"),oldPdf=new File(recovery,"pdfstudy"),live=new File(a.getFilesDir(),"pdfstudy");JSONObject old=json(new File(recovery,"notes.json"),PdfArchiveRules.META);a.db.restore(old);verifySnapshot(old,a.db.snapshot());
  if(oldPdf.exists()){
   if(live.exists()){File displaced=new File(recovery,"displaced-"+UUID.randomUUID());if(!live.renameTo(displaced))throw new IOException("현재 PDF 폴더를 보호할 수 없습니다.");}
   if(!oldPdf.renameTo(live))throw new IOException("기존 PDF 폴더를 되돌리지 못했습니다.");
  }else if(!j.getBoolean("hadOld")&&live.exists()){File displaced=new File(recovery,"displaced-"+UUID.randomUUID());if(!live.renameTo(displaced))throw new IOException("새 PDF 폴더를 되돌리지 못했습니다.");}else if(j.getBoolean("hadOld")&&!live.exists())throw new IOException("기존 PDF 복구 폴더가 없습니다. 복구 기록을 유지합니다.");
  JSONArray images=j.getJSONArray("images");for(int i=0;i<images.length();i++){String name=images.getString(i);if(!name.matches("[0-9a-fA-F-]{36}\\.img"))throw new IOException("잘못된 복구 사진 경로");new File(new File(a.getFilesDir(),"images"),name).delete();}
  j.put("phase","done");journal(a,j);finishJournal(a,j);
 }
 private static Set<String> extract(InputStream input,File folder)throws Exception{Set<String> names=new HashSet<String>();PdfArchiveRules.Budget budget=new PdfArchiveRules.Budget();try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(input))){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();long max=budget.entry(name,e.isDirectory());File file=new File(folder,name);File parent=file.getParentFile();if(!parent.isDirectory()&&!parent.mkdirs())throw new IOException("임시 공간 오류");try(OutputStream out=new FileOutputStream(file)){copy(zip,out,max,budget);}names.add(name);zip.closeEntry();}}return names;}
 private static Set<String> extractNative(File source,File folder)throws Exception{Set<String> names=new HashSet<String>();long total=0;try(ZipInputStream zip=new ZipInputStream(new BufferedInputStream(new FileInputStream(source)))){ZipEntry e;while((e=zip.getNextEntry())!=null){String name=e.getName();if(!name.equals("notes.json")&&!name.matches("images/[A-Za-z0-9_-]+\\.img"))throw new IOException("잘못된 노트 백업 경로");if(e.isDirectory()||!names.add(name)||names.size()>10001)throw new IOException("잘못된 노트 백업 항목");File target=new File(folder,name);File p=target.getParentFile();if(!p.isDirectory()&&!p.mkdirs())throw new IOException("임시 공간 오류");try(OutputStream out=new FileOutputStream(target)){total+=copy(zip,out,name.equals("notes.json")?PdfArchiveRules.META:25L*1024*1024,null);}if(total>512L*1024*1024)throw new IOException("노트 백업 크기 제한 초과");zip.closeEntry();}}if(!names.contains("notes.json"))throw new IOException("노트 정보가 없습니다.");return names;}
 private static void validateImages(File folder,Set<String> names)throws IOException{for(String name:names)if(name.startsWith("images/")){File f=new File(folder,name);BitmapFactory.Options options=new BitmapFactory.Options();options.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),options);if(options.outWidth<1||options.outHeight<1)throw new IOException("손상된 사진입니다.");int sample=1;while(options.outWidth/sample>2048||options.outHeight/sample>2048)sample*=2;options.inJustDecodeBounds=false;options.inSampleSize=sample;Bitmap image=BitmapFactory.decodeFile(f.getPath(),options);if(image==null)throw new IOException("손상된 사진입니다.");image.recycle();}}
 private static Map<String,Set<String>> noteImages(JSONObject snapshot)throws Exception{Map<String,Set<String>> out=new HashMap<String,Set<String>>();JSONArray list=snapshot.getJSONArray("notes");for(int i=0;i<list.length();i++){JSONObject n=new JSONObject(list.getJSONObject(i).getString("data"));Set<String> files=new HashSet<String>();JSONArray images=n.getJSONArray("images");for(int j=0;j<images.length();j++)files.add(images.getJSONObject(j).getString("file"));out.put(n.getString("id"),files);}return out;}
 private static String inkDoc(String name,JSONArray docs)throws Exception{for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);String id=d.getString("id"),prefix=id+"-";if(name.startsWith(prefix)&&name.endsWith(".ink.json")){String number=name.substring(prefix.length(),name.length()-9);try{int p=Integer.parseInt(number);if(p>=0&&p<d.getInt("pages"))return id;}catch(NumberFormatException ignored){}}}return null;}
 private static String hex(byte[] bytes){StringBuilder out=new StringBuilder();for(byte b:bytes){int v=b&255;out.append("0123456789abcdef".charAt(v>>>4));out.append("0123456789abcdef".charAt(v&15));}return out.toString();}
 static void verifySnapshot(JSONObject expected,JSONObject actual)throws Exception{for(String table:new String[]{"subjects","chapters","notes","history"}){JSONArray want=expected.getJSONArray(table),got=actual.getJSONArray(table);if(want.length()!=got.length())throw new IOException("복원한 노트 자료 검증에 실패했습니다.");Map<String,JSONObject> rows=new HashMap<String,JSONObject>();for(int i=0;i<got.length();i++){JSONObject row=got.getJSONObject(i);rows.put(row.get("id").toString(),row);}for(int i=0;i<want.length();i++){JSONObject row=want.getJSONObject(i),other=rows.get(row.get("id").toString());if(other==null||row.length()!=other.length())throw new IOException("복원한 노트 자료가 일치하지 않습니다.");Iterator<String> keys=row.keys();while(keys.hasNext()){String key=keys.next();if(!row.get(key).toString().equals(other.get(key).toString()))throw new IOException("복원한 노트 자료가 일치하지 않습니다.");}}}}
 private static String digest(File file)throws Exception{MessageDigest hash=MessageDigest.getInstance("SHA-256");try(InputStream in=new DigestInputStream(new FileInputStream(file),hash)){byte[] bytes=new byte[65536];while(in.read(bytes)!=-1){}}return hex(hash.digest());}
 static void validateReferences(JSONObject snapshot)throws Exception{Map<String,Set<String>> images=noteImages(snapshot);JSONArray rows=snapshot.getJSONArray("notes");for(int i=0;i<rows.length();i++){JSONObject n=new JSONObject(rows.getJSONObject(i).getString("data"));for(String key:new String[]{"body","question","answer","mine","reason","caution"})for(String file:InlineImageText.files(n.optString(key)))if(!images.get(n.getString("id")).contains(file))throw new IOException("본문 사진이 누락된 백업입니다.");}}
 private static void validateMetadata(JSONObject metadata,JSONObject snapshot,Set<String> entries,File folder)throws Exception{
  JSONArray docs=metadata.getJSONArray("docs");JSONObject notes=metadata.optJSONObject("notes");if(notes==null){notes=new JSONObject();metadata.put("notes",notes);}Map<String,Integer> pages=new HashMap<String,Integer>();
  for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);String id=d.getString("id");PdfArchiveRules.id(id);if(pages.containsKey(id)||!entries.contains("pdf/"+id+".pdf"))throw new IOException("중복 또는 누락된 PDF 원본입니다.");File file=new File(folder,id+".pdf");int count;try(ParcelFileDescriptor fd=ParcelFileDescriptor.open(file,ParcelFileDescriptor.MODE_READ_ONLY);PdfRenderer renderer=new PdfRenderer(fd)){count=renderer.getPageCount();}if(count<1||count!=d.getInt("pages"))throw new IOException("PDF 페이지 정보가 일치하지 않습니다.");String sha=digest(file);if(d.has("sha256")&&!sha.equalsIgnoreCase(d.getString("sha256")))throw new IOException("PDF 원본 검증값이 일치하지 않습니다.");d.put("sha256",sha).put("bytes",file.length());pages.put(id,count);int page=d.optInt("page",0);if(page<0||page>=count)throw new IOException("잘못된 마지막 페이지 정보");JSONArray bookmarks=d.optJSONArray("bookmarks");if(bookmarks!=null)for(int j=0;j<bookmarks.length();j++){JSONObject mark=bookmarks.getJSONObject(j);int p=mark.getInt("page");if(p<0||p>=count||!(mark.get("title") instanceof String)||!(mark.get("category") instanceof String))throw new IOException("잘못된 책갈피 정보");}for(String key:new String[]{"zoom","panX","panY"})if(d.has(key)){double v=d.getDouble(key);if(Double.isNaN(v)||Double.isInfinite(v))throw new IOException("잘못된 PDF 화면 정보");}long offset=d.optLong("bookOffset",0);if(offset< -1000000||offset>1000000)throw new IOException("잘못된 인쇄 쪽수 정보");d.remove("uri");}
  for(String name:entries)if(name.startsWith("pdf/")&&!name.equals("pdf/state.json")){String file=name.substring(4);if(file.endsWith(".pdf")){if(!pages.containsKey(file.substring(0,file.length()-4)))throw new IOException("등록되지 않은 PDF 원본");}else{if(inkDoc(file,docs)==null)throw new IOException("등록되지 않은 페이지 필기");validateInk(new File(folder,file));}}
  Map<String,Set<String>> images=noteImages(snapshot);Iterator<String> ids=notes.keys();while(ids.hasNext()){String id=ids.next();if(!images.containsKey(id))throw new IOException("노트가 누락된 PDF 연결 정보");JSONObject record=notes.getJSONObject(id);JSONArray clips=record.getJSONArray("clips");for(int i=0;i<clips.length();i++){JSONObject clip=clips.getJSONObject(i);String doc=clip.getString("doc");Integer count=pages.get(doc);int page=clip.getInt("page"),role=clip.getInt("role");if(count==null||page<0||page>=count||role<0||role>2)throw new IOException("잘못된 PDF 출처 정보");String file=clip.getString("file");if(!file.isEmpty()&&!images.get(id).contains(file))throw new IOException("사진이 누락된 PDF 출처 정보");if(file.isEmpty()&&!clip.has("text"))throw new IOException("내용이 없는 PDF 출처 정보");}}
 }
 private static void validateInk(File file)throws Exception{JSONObject ink;try(InputStream in=new AtomicFile(file).openRead();ByteArrayOutputStream out=new ByteArrayOutputStream()){copy(in,out,PdfArchiveRules.INK,null);ink=new JSONObject(new String(out.toByteArray(),StandardCharsets.UTF_8));}validateInkData(ink);}
 static void validateInkData(JSONObject ink)throws Exception{if(ink.getInt("version")!=1)throw new IOException("지원하지 않는 PDF 필기");JSONArray strokes=ink.getJSONArray("strokes");for(int i=0;i<strokes.length();i++){JSONObject s=strokes.getJSONObject(i);s.getInt("color");double w=s.getDouble("width");if(Double.isNaN(w)||Double.isInfinite(w)||w<=0||w>1)throw new IOException("잘못된 필기 굵기");JSONArray points=s.getJSONArray("points");if(points.length()<2||points.length()%2!=0)throw new IOException("잘못된 필기 좌표");for(int j=0;j<points.length();j++){double p=points.getDouble(j);if(Double.isNaN(p)||Double.isInfinite(p)||p<0||p>1)throw new IOException("잘못된 필기 좌표");}}}
 private static void pruneOrphans(JSONObject state,JSONObject snapshot)throws Exception{Map<String,Set<String>> images=noteImages(snapshot);JSONArray docs=state.optJSONArray("docs");Set<String> docIds=new HashSet<String>();if(docs!=null)for(int i=0;i<docs.length();i++){JSONObject d=docs.getJSONObject(i);docIds.add(d.getString("id"));if(!images.containsKey(d.optString("current")))d.put("current","");}JSONObject old=state.optJSONObject("notes"),clean=new JSONObject();if(old!=null){Iterator<String> ids=old.keys();while(ids.hasNext()){String id=ids.next();if(!images.containsKey(id))continue;JSONObject r=old.getJSONObject(id);JSONArray clips=r.optJSONArray("clips"),kept=new JSONArray();if(clips!=null)for(int i=0;i<clips.length();i++){JSONObject c=clips.getJSONObject(i);String file=c.optString("file");if(docIds.contains(c.optString("doc"))&&(file.isEmpty()?c.has("text"):images.get(id).contains(file)))kept.put(c);}if(kept.length()>0){r.put("clips",kept).put("doc",kept.getJSONObject(0).getString("doc"));clean.put(id,r);}}}state.put("notes",clean);}
 private static void remap(JSONObject snapshot,JSONObject state,Map<String,String> mapping)throws Exception{JSONArray rows=snapshot.getJSONArray("notes");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i),n=new JSONObject(row.getString("data"));JSONArray images=n.getJSONArray("images");for(int j=0;j<images.length();j++){JSONObject im=images.getJSONObject(j);String next=mapping.get(im.getString("file"));if(next==null)throw new IOException("누락된 사진 매핑");im.put("file",next);}for(String key:new String[]{"body","question","answer","mine","reason","caution"})n.put(key,InlineImageText.remap(n.optString(key),mapping));JSONArray ink=n.optJSONArray("ink");if(ink!=null)for(int j=0;j<ink.length();j++){JSONObject stroke=ink.getJSONObject(j);String key=stroke.optString("key");if(key.startsWith("image:")){String next=mapping.get(key.substring(6));if(next!=null)stroke.put("key","image:"+next);}}row.put("data",n.toString());}JSONObject notes=state.getJSONObject("notes");Iterator<String> ids=notes.keys();while(ids.hasNext()){JSONArray clips=notes.getJSONObject(ids.next()).getJSONArray("clips");for(int i=0;i<clips.length();i++){JSONObject c=clips.getJSONObject(i);String f=c.getString("file");if(!f.isEmpty())c.put("file",mapping.get(f));}}}
}
